<script>
  import { $state, $derived, $on } from 'svelte/rune';

  const { state, update } = $state('');
  const { derived } = $derived;

  $on(state, 'update', (newValue) => {
    update(newValue);
  });

  const wordCount = derived.by(state, (text) => {
    return text.trim().split(/\s+/).length;
  });

  const charCount = derived.by(state, (text) => {
    return text.length;
  });

  const isLong = derived.by(state, (text) => {
    return wordCount > 15;
  });
</script>

<div>
  <input data-testid="text-input" type="text" bind:value="{state}" />
  <button data-testid="clear-button" on:click={() => update('')}>Clear</button>
  <div>
    <p data-testid="word-count">Words: {wordCount}</p>
    <p data-testid="char-count">Characters: {charCount}</p>
    <p data-testid="length-indicator">{isLong ? 'Long text' : 'Short text'}</p>
  </div>
</div>
