<script>
  import { $state, $inspect, $effect } from '$svelte/rune';

  const text = $state('Hello world');

  $inspect(text).log();

  $inspect(text).with((value) => {
    console.log('Input updated with:', value);
  });

  $effect(() => {
    $inspect().trace('Input changed');
  }, [text]);

</script>

<div>
  <input data-testid="text-input" type="text" bind:value={$state(text)} />
  <p data-testid="text-value">Current text: "{text}"</p>
  <p data-testid="char-count">Character count: {text.length}</p>
</div>
