<script>
  $props({
    name: 'World',
    count: $state(0),
    showDetails: false
  });

  $effect(() => {
    document.getElementById('increment-button').addEventListener('click', () => {
      $state.count += 1;
    });
  });
</script>

<div>
  <h1 data-testid="name-display">Hello, {name}!</h1>
  <p data-testid="count-display">Count: {count}</p>
  <button data-testid="increment-button">Increment</button>

  {$showDetails ? (
    <div data-testid="details">
      <p>Name is {name}</p>
      <p>Count is {count}</p>
      <p>ShowDetails is {showDetails}</p>
    </div>
  ) : null}
</div>
